ALTER TABLE employment_and_income ADD COLUMN fsi numeric;

DO $$
DECLARE
    rec RECORD;
    v_liqassets numeric;
    v_savamount numeric;
    v_bankaccbal numeric;
BEGIN
    FOR rec IN 
        SELECT e.emplcoreref, e.debincratio, e.mthincome, ea.liqassets, ea.savamount, ea.bankaccbal
        FROM employment_and_income e
        JOIN expenses_and_assets ea ON e.emplcoreref = ea.expemplref
    LOOP
        v_liqassets := rec.liqassets;
        v_savamount := rec.savamount;
        v_bankaccbal := rec.bankaccbal;

        UPDATE employment_and_income
        SET fsi = CASE 
            WHEN rec.mthincome > 0 THEN
                0.3 * LEAST(1.0, GREATEST(0, 1 - rec.debincratio))
                + 0.3 * LEAST(1.0, v_liqassets / (CAST(rec.mthincome AS numeric) * 6))
                + 0.2 * LEAST(1.0, v_bankaccbal / (CAST(rec.mthincome AS numeric) * 3))
                + 0.2 * LEAST(1.0, v_savamount / (CAST(rec.mthincome AS numeric) * 12))
            ELSE NULL
        END
        WHERE emplcoreref = rec.emplcoreref;
    END LOOP;
END $$;
